CREATE OR REPLACE FUNCTION public.reserve_governance_action(_decision_id uuid,_command text,_group_id uuid DEFAULT NULL,_compromise boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.public_decisions;cid uuid;s public.governance_settings;m public.municipal_mandates;lid uuid;aid uuid;action_id uuid;minutes integer;t timestamptz:=public.game_now();g public.municipal_council_groups; BEGIN
SELECT * INTO d FROM public.public_decisions WHERE id=_decision_id AND mandate_id IS NOT NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Dossier introuvable'; END IF;cid:=public.governance_owner(d.mandate_id); SELECT * INTO d FROM public.public_decisions WHERE id=_decision_id FOR UPDATE; SELECT * INTO m FROM public.municipal_mandates WHERE id=d.mandate_id; SELECT * INTO s FROM public.governance_settings WHERE id=1;
IF _command NOT IN('study','negotiate','vote') OR _command IS NULL OR d.workflow NOT IN('idea','study','proposed') THEN RAISE EXCEPTION 'Action indisponible à cette étape'; END IF;
IF _command='study' AND d.studied_at IS NOT NULL THEN RAISE EXCEPTION 'Étude déjà terminée'; END IF;
IF _command IN('negotiate','vote') AND d.studied_at IS NULL THEN RAISE EXCEPTION 'Terminez l’étude avant la discussion ou le vote'; END IF;
IF _command='negotiate' THEN SELECT * INTO g FROM public.municipal_council_groups WHERE id=_group_id AND mandate_id=d.mandate_id; IF NOT FOUND THEN RAISE EXCEPTION 'Groupe inaccessible'; END IF; IF EXISTS(SELECT 1 FROM public.governance_positions WHERE decision_id=d.id AND group_id=g.id AND negotiated) THEN RAISE EXCEPTION 'Discussion déjà effectuée avec ce groupe'; END IF; END IF;
SELECT location_id INTO lid FROM public.institutions WHERE id=d.institution_id;
minutes:=CASE _command WHEN 'study' THEN s.study_minutes WHEN 'negotiate' THEN s.negotiation_minutes ELSE s.vote_minutes END;
IF t+minutes*interval '1 minute'>m.ends_at THEN RAISE EXCEPTION 'Le mandat expire avant la fin de cette activité'; END IF;
IF EXISTS(SELECT 1 FROM public.activities WHERE character_id=cid AND status IN('planned','running') AND start_time<t+minutes*interval '1 minute' AND end_time>t) THEN RAISE EXCEPTION 'Cette activité chevauche votre agenda'; END IF;
IF (SELECT energy FROM public.characters WHERE id=cid)<s.energy_cost THEN RAISE EXCEPTION 'Énergie insuffisante'; END IF;
DELETE FROM public.governance_actions ga USING public.activities a WHERE ga.activity_id=a.id AND ga.decision_id=d.id AND ga.command=_command AND ga.group_id IS NOT DISTINCT FROM CASE WHEN _command='negotiate' THEN _group_id END AND a.status='cancelled' AND ga.settled_at IS NULL;
INSERT INTO public.governance_actions(decision_id,character_id,command,group_id,compromise) VALUES(d.id,cid,_command,CASE WHEN _command='negotiate' THEN _group_id END,COALESCE(_compromise,false)) RETURNING id INTO action_id;
INSERT INTO public.activities(character_id,type,title,start_time,end_time,location_id,energy_cost,status,source_key,governance_action_id) VALUES(cid,'governance',CASE _command WHEN 'study' THEN 'Étude — ' WHEN 'negotiate' THEN 'Discussion du conseil — ' ELSE 'Vote du conseil — ' END||d.title,t,t+minutes*interval '1 minute',lid,s.energy_cost,'planned','governance:'||action_id,action_id) RETURNING id INTO aid;
UPDATE public.governance_actions SET activity_id=aid WHERE id=action_id;
IF _command='study' THEN UPDATE public.public_decisions SET workflow='study' WHERE id=d.id; ELSIF _command='vote' THEN UPDATE public.public_decisions SET workflow='proposed',proposed_at=t WHERE id=d.id; END IF;
RETURN aid; END $$;
REVOKE ALL ON FUNCTION public.reserve_governance_action(uuid,text,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reserve_governance_action(uuid,text,uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.governance_activity_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ac public.governance_actions;d public.public_decisions;m public.municipal_mandates;BEGIN
IF NEW.type<>'governance' THEN RETURN NEW; END IF;
SELECT * INTO ac FROM public.governance_actions WHERE id=NEW.governance_action_id AND character_id=NEW.character_id; IF NOT FOUND THEN RAISE EXCEPTION 'Réservez une activité du mandat'; END IF;
SELECT * INTO d FROM public.public_decisions WHERE id=ac.decision_id;SELECT * INTO m FROM public.municipal_mandates WHERE id=d.mandate_id;
IF TG_OP='INSERT' THEN IF NEW.status<>'planned' OR ac.activity_id IS NOT NULL THEN RAISE EXCEPTION 'Réservation invalide'; END IF;
ELSIF NEW.status='running' AND OLD.status='planned' THEN
IF public.game_now()<m.starts_at OR public.game_now()>=m.ends_at OR m.status<>'active' OR NOT EXISTS(SELECT 1 FROM public.candidacies ca JOIN public.characters c ON c.id=ca.character_id WHERE ca.id=m.candidacy_id AND c.id=NEW.character_id AND c.user_id=auth.uid()) OR NEW.end_time>m.ends_at OR d.workflow NOT IN('study','proposed') THEN RAISE EXCEPTION 'Mandat ou procédure expirée'; END IF;
ELSIF NEW.status='completed' THEN IF OLD.status<>'running' OR NEW.end_time>public.game_now() THEN RAISE EXCEPTION 'Activité non achevée'; END IF; END IF;
IF NEW.money_cost<>0 OR NEW.reward<>0 OR NEW.progression_gain<>0 OR NEW.energy_gain<>0 OR NEW.political_reputation_gain<>0 OR NEW.political_influence_gain<>0 OR NEW.social_reputation_gain<>0 THEN RAISE EXCEPTION 'Récompense de mandat invalide'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER governance_activity_guard BEFORE INSERT OR UPDATE ON public.activities FOR EACH ROW EXECUTE FUNCTION public.governance_activity_guard(); REVOKE ALL ON FUNCTION public.governance_activity_guard() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.start_life_activity(text,uuid,uuid)'::regprocedure) INTO def; def:=replace(def,'_type IN(''course'',''social'')','_type IN(''course'',''social'',''governance'')'); def:=replace(def,'a.type=''social''','a.type IN(''social'',''governance'')'); EXECUTE def; END $$;
CREATE OR REPLACE FUNCTION public.settle_governance_action() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ac public.governance_actions;d public.public_decisions;g public.municipal_council_groups;pos public.governance_positions;yes_count integer:=0;no_count integer:=0;abstain_count integer:=0;sup integer;details jsonb:='[]';change integer;BEGIN
IF NEW.type<>'governance' OR NEW.status<>'completed' OR OLD.status<>'running' OR NEW.end_time>public.game_now() THEN RETURN NEW; END IF;
SELECT * INTO ac FROM public.governance_actions WHERE id=NEW.governance_action_id FOR UPDATE; IF ac.settled_at IS NOT NULL THEN RETURN NEW; END IF;
SELECT * INTO d FROM public.public_decisions WHERE id=ac.decision_id; PERFORM pg_advisory_xact_lock(hashtextextended('civic:'||d.city_id,0)); SELECT * INTO d FROM public.public_decisions WHERE id=ac.decision_id FOR UPDATE;
UPDATE public.governance_actions SET settled_at=NEW.end_time WHERE id=ac.id;
IF ac.command='study' THEN UPDATE public.public_decisions SET studied_at=NEW.end_time,workflow='study' WHERE id=d.id;
ELSIF ac.command='negotiate' THEN SELECT * INTO g FROM public.municipal_council_groups WHERE id=ac.group_id; change:=CASE WHEN ac.compromise THEN 20 ELSE 8 END; IF g.leader_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.social_relations WHERE character_id=ac.character_id AND npc_id=g.leader_id AND score>=20) THEN change:=change+5; END IF;
UPDATE public.governance_positions SET support=LEAST(100,support+change),negotiated=true,reaction=CASE WHEN support+change>=50 THEN 'Soutien après discussion' ELSE 'Réserves maintenues' END WHERE decision_id=d.id AND group_id=g.id;
IF ac.compromise THEN UPDATE public.public_decisions SET compromise=true WHERE id=d.id; END IF;
IF g.leader_id IS NOT NULL THEN INSERT INTO public.social_relations(character_id,npc_id,score,status,met_at,last_interaction) VALUES(ac.character_id,g.leader_id,5,'acquaintance',NEW.end_time,NEW.end_time) ON CONFLICT(character_id,npc_id) DO UPDATE SET score=LEAST(100,social_relations.score+5),last_interaction=NEW.end_time; END IF;
PERFORM public.governance_news(d.id,'discussion:'||g.id,g.name||' réagit au dossier',CASE WHEN ac.compromise THEN 'Un compromis réduit de 20 % les bénéfices attendus ; le coût de réalisation reste inchangé. Le vote demeure indépendant.' ELSE 'Les échanges ont fait évoluer le soutien sans achat de voix.' END,NEW.end_time,'reaction');
ELSIF ac.command='vote' THEN
FOR pos IN SELECT * FROM public.governance_positions WHERE decision_id=d.id ORDER BY group_id LOOP SELECT * INTO g FROM public.municipal_council_groups WHERE id=pos.group_id; sup:=pos.support; IF sup>=50 THEN yes_count:=yes_count+g.seats; ELSIF sup>=40 THEN abstain_count:=abstain_count+g.seats; ELSE no_count:=no_count+g.seats; END IF; details:=details||jsonb_build_array(jsonb_build_object('id',g.id,'seats',g.seats,'support',sup,'vote',CASE WHEN sup>=50 THEN 'Pour' WHEN sup>=40 THEN 'Abstention' ELSE 'Contre' END)); END LOOP;
UPDATE public.public_decisions SET voted_at=NEW.end_time,workflow=CASE WHEN yes_count>(yes_count+no_count+abstain_count)/2 THEN 'approved' ELSE 'rejected' END,council_result=jsonb_build_object('yes',yes_count,'no',no_count,'abstention',abstain_count,'total',yes_count+no_count+abstain_count,'adopted',yes_count>(yes_count+no_count+abstain_count)/2,'groups',details) WHERE id=d.id;
PERFORM public.governance_news(d.id,'vote',CASE WHEN yes_count>(yes_count+no_count+abstain_count)/2 THEN 'Le conseil adopte — ' ELSE 'Le conseil rejette — ' END||d.title,yes_count||' pour, '||no_count||' contre, '||abstain_count||' abstentions. Le résultat ne finance pas automatiquement le projet.',NEW.end_time,'council');
END IF;
INSERT INTO public.notifications(user_id,title,body,world_at) SELECT c.user_id,'Activité du mandat terminée',NEW.title,NEW.end_time FROM public.characters c LEFT JOIN public.user_settings s ON s.user_id=c.user_id WHERE c.id=ac.character_id AND COALESCE(s.notifications_enabled,true);
RETURN NEW; END $$;
CREATE TRIGGER governance_activity_settlement AFTER UPDATE OF status ON public.activities FOR EACH ROW EXECUTE FUNCTION public.settle_governance_action(); REVOKE ALL ON FUNCTION public.settle_governance_action() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.open_governance_consultation(_decision_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.public_decisions;cid uuid;coid uuid;s public.governance_settings;BEGIN SELECT * INTO d FROM public.public_decisions WHERE id=_decision_id AND mandate_id IS NOT NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Dossier introuvable'; END IF;cid:=public.governance_owner(d.mandate_id); SELECT * INTO d FROM public.public_decisions WHERE id=d.id FOR UPDATE; IF d.consultation_id IS NOT NULL OR d.workflow NOT IN('idea','study','proposed') THEN RAISE EXCEPTION 'Consultation indisponible'; END IF; SELECT * INTO s FROM public.governance_settings WHERE id=1;
INSERT INTO public.consultations(consultation_key,institution_id,city_id,district_id,location_id,title,description,starts_at,ends_at,advisory,governance_decision_id) VALUES('governance:'||d.id,d.institution_id,d.city_id,d.district_id,d.location_id,'Votre avis — '||d.title,'Consultation indicative : le conseil vote séparément et le financement reste soumis au budget.',public.game_now(),public.game_now()+s.consultation_hours*interval '1 hour',true,d.id) RETURNING id INTO coid;
INSERT INTO public.consultation_options(consultation_id,label,consequence,sort_order) VALUES(coid,'Soutenir le projet','Avis favorable transmis au conseil.',0),(coid,'Demander une modification','Demande de compromis transmise au conseil.',1),(coid,'S’opposer au projet','Avis défavorable transmis au conseil.',2);
UPDATE public.public_decisions SET consultation_id=coid WHERE id=d.id; PERFORM public.governance_news(d.id,'consultation','Consultation ouverte — '||d.title,'Les habitants sont invités à donner un avis consultatif.',public.game_now(),'consultation');RETURN coid;END $$;
REVOKE ALL ON FUNCTION public.open_governance_consultation(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.open_governance_consultation(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.fund_municipal_project(_decision_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.public_decisions;cid uuid;tr public.municipal_treasuries;failed boolean;delay integer;BEGIN
SELECT * INTO d FROM public.public_decisions WHERE id=_decision_id AND mandate_id IS NOT NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Dossier introuvable'; END IF;cid:=public.governance_owner(d.mandate_id);SELECT * INTO d FROM public.public_decisions WHERE id=_decision_id FOR UPDATE;
IF d.workflow<>'approved' OR d.funded_at IS NOT NULL OR COALESCE((d.council_result->>'adopted')::boolean,false)=false OR d.cost IS NULL OR d.cost<=0 THEN RAISE EXCEPTION 'Projet non approuvé ou déjà financé'; END IF;
IF EXISTS(SELECT 1 FROM public.public_decisions WHERE location_id=d.location_id AND id<>d.id AND mandate_id IS NOT NULL AND workflow='running') THEN RAISE EXCEPTION 'Un chantier est déjà en cours dans ce lieu'; END IF;
SELECT * INTO tr FROM public.municipal_treasuries WHERE city_id=d.city_id FOR UPDATE;IF tr.balance-tr.reserve<d.cost THEN RAISE EXCEPTION 'Budget municipal disponible insuffisant'; END IF;
failed:=mod(abs(hashtext(d.id::text||':failure')::bigint),100)<COALESCE((d.rule_snapshot->>'risk')::integer,0); delay:=CASE WHEN mod(abs(hashtext(d.id::text||':delay')::bigint),100)<20 THEN 3 ELSE 0 END;
INSERT INTO public.municipal_ledger(city_id,entry_key,decision_id,category,amount,label) VALUES(d.city_id,'fund:'||d.id,d.id,d.rule_snapshot->>'category',-d.cost,'Financement — '||d.title);
UPDATE public.municipal_treasuries SET balance=balance-d.cost,expenses=expenses+d.cost WHERE city_id=d.city_id;
UPDATE public.public_decisions SET funded_at=public.game_now(),ends_at=public.game_now()+(duration_days+delay)*interval '1 day',workflow='running',failure=failed,delay_days=delay,status='applied',decided_at=public.game_now(),consequences=jsonb_build_object('project',title,'state','travaux') WHERE id=d.id RETURNING * INTO d;
INSERT INTO public.governance_effects(decision_id,effect_key,due_at,deltas,kind) VALUES(d.id,d.id||':immediate',d.funded_at,COALESCE(d.rule_snapshot->'immediate','{}'),'immediate'),(d.id,d.id||':completion',d.ends_at,CASE WHEN failed THEN COALESCE(d.rule_snapshot->'failure_delta','{"satisfaction":-3}') ELSE COALESCE(d.rule_snapshot->'completion','{}') END,'completion'),(d.id,d.id||':delayed',d.ends_at+COALESCE((d.rule_snapshot->>'delayed_days')::integer,7)*interval '1 day',CASE WHEN failed THEN '{}'::jsonb ELSE COALESCE(d.rule_snapshot->'delayed','{}') END,'delayed');
PERFORM public.governance_news(d.id,'funding','Chantier financé — '||d.title,'Le budget municipal finance '||d.cost||' €. Les perturbations et bénéfices seront appliqués aux échéances du monde.',d.funded_at,'announcement');
IF delay>0 THEN PERFORM public.governance_news(d.id,'delay','Retard annoncé — '||d.title,'Une contrainte technique allonge le chantier de '||delay||' jours du monde, sans débit supplémentaire.',d.funded_at,'incident'); END IF;END $$;
REVOKE ALL ON FUNCTION public.fund_municipal_project(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.fund_municipal_project(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.abandon_municipal_dossier(_decision_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.public_decisions;cid uuid;BEGIN SELECT * INTO d FROM public.public_decisions WHERE id=_decision_id AND mandate_id IS NOT NULL;IF NOT FOUND THEN RAISE EXCEPTION 'Dossier introuvable';END IF;cid:=public.governance_owner(d.mandate_id);SELECT * INTO d FROM public.public_decisions WHERE id=_decision_id FOR UPDATE; IF d.funded_at IS NOT NULL OR d.workflow IN('rejected','abandoned') OR EXISTS(SELECT 1 FROM public.governance_actions ga JOIN public.activities a ON a.id=ga.activity_id WHERE ga.decision_id=d.id AND a.status IN('planned','running')) THEN RAISE EXCEPTION 'Terminez ou annulez les activités ; un chantier financé ne peut plus être abandonné';END IF;UPDATE public.public_decisions SET workflow='abandoned',completed_at=public.game_now() WHERE id=d.id;END $$;
REVOKE ALL ON FUNCTION public.abandon_municipal_dossier(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.abandon_municipal_dossier(uuid) TO authenticated;